<!-- This file is generated by AI. -->

<!--
  新建项目对话框: 名称 + 存放位置 + 引擎 (+ 可选模板)。

  项目骨架来自引擎: WebGAL 的"项目"就是一份引擎发行包, 因此这里先选引擎, 再可选地
  用模板覆盖引擎内置模板。没有任何引擎时不给"创建"按钮, 而是直接引到"引擎"设置页。
-->

<script lang="ts">
  import { open } from '@tauri-apps/plugin-dialog';

  import { engineLabel } from '../lib/engine';
  import { joinPath, sanitizeFolderName } from '../lib/paths';
  import { createProject } from '../project';
  import { appStore } from '../state/store.svelte';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Input from './Input.svelte';
  import Select from './Select.svelte';

  let { onClose, onOpenEngineSettings }: { onClose: () => void; onOpenEngineSettings: () => void } = $props();

  const settings = $derived(appStore.settings);

  let name = $state('');
  let directory = $state('');
  /*
   * 引擎默认选第一个 (未绑定项目的默认引擎)。
   *
   * 初值只在挂载时读一次 —— 对话框每次打开都是新实例, 用户在选择过程中改动引擎不该被外部变化
   * 重置。Svelte 的 `state_referenced_locally` 在此是误报 (它不认识"有意只取一次"的用法)。
   */
  // svelte-ignore state_referenced_locally
  let engineId = $state(settings.engines[0]?.id ?? '');
  let templateId = $state('');
  let busy = $state(false);
  let error = $state<string | null>(null);

  const engineOptions = $derived(settings.engines.map((engine) => ({ value: engine.id, label: engineLabel(engine) })));
  const templateOptions = $derived([
    { value: '', label: '跟随引擎内置模板' },
    ...settings.templates.map((template) => ({ value: template.id, label: template.name })),
  ]);

  const target = $derived(directory && name.trim() ? joinPath(directory, sanitizeFolderName(name.trim())) : '');
  const canSubmit = $derived(name.trim() !== '' && directory !== '' && engineId !== '' && !busy);

  async function pickDirectory(): Promise<void> {
    const dir = await open({ directory: true, title: '选择项目存放位置' });
    if (typeof dir === 'string') directory = dir;
  }

  async function submit(): Promise<void> {
    error = null;
    busy = true;
    try {
      // `createProject` 内部负责复制引擎骨架、写配置、记绑定并接着打开项目 ——
      // 用户按下"创建"就是想开始写。
      await createProject({
        path: target,
        name: name.trim(),
        engineId,
        templateId: templateId || null,
      });
      onClose();
    } catch (e) {
      error = String(e);
    } finally {
      busy = false;
    }
  }
</script>

<AppDialog
  title="新建项目"
  description="由引擎复制出一份完整的项目骨架，可再套用模板。"
  size="form"
  closeOnBackdrop={!busy}
  {onClose}
>
  <div class="settings-field">
    <span class="settings-label">项目名称</span>
    <Input bind:value={name} placeholder="显示在游戏标题界面的名称" />
  </div>

  <div class="settings-field">
    <span class="settings-label">存放位置</span>
    <div class="input-row">
      <!--
        只读路径字段: 路径必须来自"浏览"按钮选的目录, 手打一个不存在的路径只会到创建时才报错。
        这里用**原生 `<input readonly>`** 而不是 `ui/Input.svelte` —— 后者没有暴露 `readonly`;
        类名仍是 `.ui-input`, 因此外观与旁边的输入框完全一致。
      -->
      <input class="ui-input" readonly value={directory} placeholder="选择项目存放的父目录" />
      <Button icon="FolderOpen" title="选择项目存放位置" disabled={busy} onclick={() => void pickDirectory()} />
    </div>
  </div>

  {#if settings.engines.length === 0}
    <div class="settings-field">
      <span class="settings-label">引擎</span>
      <p class="muted">还没有添加 WebGAL 引擎。项目骨架来自引擎，请先添加一个。</p>
      <Button onclick={onOpenEngineSettings}>去添加引擎</Button>
    </div>
  {:else}
    <div class="settings-field">
      <span class="settings-label">引擎</span>
      <Select value={engineId} options={engineOptions} disabled={busy} onchange={(next) => (engineId = next)} />
    </div>

    <div class="settings-field">
      <span class="settings-label">模板</span>
      <Select value={templateId} options={templateOptions} disabled={busy} onchange={(next) => (templateId = next)} />
    </div>
  {/if}

  {#if target}
    <p class="dialog-hint" title={target}>{target}</p>
  {/if}
  {#if error}
    <p class="prompt-error">{error}</p>
  {/if}

  {#snippet footer()}
    <Button onclick={onClose} disabled={busy}>取消</Button>
    <Button appearance="primary" onclick={() => void submit()} disabled={!canSubmit}>
      {busy ? '正在创建…' : '创建'}
    </Button>
  {/snippet}
</AppDialog>
